async function api(url,options={}){
 const method=options.method||'GET';const payload=options.body instanceof FormData?options.body:options.body?JSON.parse(options.body):null;
 if(url==='/login'){if(!payload.email.includes('@')){const {data:lookup,error:lookupError}=await supabase.functions.invoke('login-cliente',{body:{username:payload.email,password:payload.password}});if(lookupError||!lookup?.access_token||!lookup?.refresh_token)throw Error('Usuário ou senha inválidos');check(await supabase.auth.setSession({access_token:lookup.access_token,refresh_token:lookup.refresh_token}));const d=check(await supabase.auth.getUser());const p=check(await supabase.from('profiles').select('role').eq('id',d.user.id).single());return{id:d.user.id,email:d.user.email,displayName:d.user.user_metadata?.display_name||'',role:p.role};}const d=check(await supabase.auth.signInWithPassword(payload));const p=check(await supabase.from('profiles').select('role').eq('id',d.user.id).single());return{id:d.user.id,email:d.user.email,role:p.role};}
 if(url==='/logout'){check(await supabase.auth.signOut());return{ok:true};}
 if(url==='/me'){const d=check(await supabase.auth.getUser());if(!d.user)throw Error('Não autenticado');const p=check(await supabase.from('profiles').select('role').eq('id',d.user.id).single());return{id:d.user.id,email:d.user.email,role:p.role};}
 if(url==='/markets'){if(method==='POST')return check(await supabase.from('markets').insert(payload).select('id').single());return check(await supabase.from('markets').select('*').order('name'));}
 if(url==='/manage-clients'){const {data,error}=await supabase.functions.invoke('gerenciar-clientes',{body:payload||{action:'list'}});if(error){let msg=error.message;try{const detail=await error.context?.json();msg=detail?.error||msg}catch{}throw Error(msg)}if(data?.error)throw Error(data.error);return data;}
 if(url==='/clients'){if(method==='POST'){const {data,error}=await supabase.functions.invoke('cadastrar-cliente',{body:payload});if(error){let msg=error.message;try{const response=error.context;if(response&&typeof response.json==='function'){const detail=await response.json();msg=detail.error||msg;}}catch{}throw Error(msg)}if(data?.error)throw Error(data.error);return data;}const rows=check(await supabase.from('profiles').select('id,role').eq('role','client'));return rows;}
 if(url==='/storage'){const rows=check(await supabase.from('attachments').select('id'));const old=check(await supabase.from('occurrences').select('id,created_at'));return{files:rows.length,bytes:0,expiringSoon:old.filter(x=>Date.now()-Date.parse(x.created_at)>=25*86400000).length};}
 if(url==='/occurrences'){
  if(method==='POST')return check(await supabase.from('occurrences').insert({market_id:payload.market_id,type:payload.type,occurred_on:payload.date,occurred_at:payload.time,description:payload.description}).select('id').single());
  const rows=check(await supabase.from('occurrences').select('*,markets(name,plan),attachments(id,original_name,mime_type,storage_path)').order('occurred_on',{ascending:false}));
  return Promise.all(rows.map(async o=>({...o,date:o.occurred_on,time:o.occurred_at?.slice(0,5),market:o.markets?.name,plan:o.markets?.plan,attachments:await Promise.all((o.attachments||[]).map(async a=>{const {data,error}=await supabase.storage.from('ocorrencias').createSignedUrl(a.storage_path,300);return{id:a.id,original_name:a.original_name,mime:a.mime_type,url:error?'':data.signedUrl};}))})));
 }
 const uploadMatch=url.match(/^\/occurrences\/(\d+)\/attachments$/);
 if(uploadMatch&&method==='POST'){let count=0;for(const file of payload.getAll('files')){if(file.size>50*1024*1024)throw Error('Arquivo maior que 50 MB');const path=uploadMatch[1]+'/'+crypto.randomUUID();check(await supabase.storage.from('ocorrencias').upload(path,file,{contentType:file.type,upsert:false}));try{check(await supabase.from('attachments').insert({occurrence_id:Number(uploadMatch[1]),storage_path:path,original_name:file.name,mime_type:file.type}));}catch(e){await supabase.storage.from('ocorrencias').remove([path]);throw e;}count++;}return{count};}
 const del=url.match(/^\/occurrences\/(\d+)$/);
 if(del&&method==='DELETE'){const id=Number(del[1]);const a=check(await supabase.from('attachments').select('storage_path').eq('occurrence_id',id));if(a.length)check(await supabase.storage.from('ocorrencias').remove(a.map(x=>x.storage_path)));check(await supabase.from('occurrences').delete().eq('id',id));return{ok:true};}
 throw Error('Operação indisponível');
}
