const openDate=async date=>{setShowCalendar(false);setSelectedDate(date);setHistoryMonth(date.slice(0,7));setCalendarMonth(date.slice(0,7));if(user?.role!=='client')return;const pending=items.filter(o=>o.date===date&&String(o.market_id)===String(selectedMarket)&&!reads.some(r=>String(r.occurrence_id)===String(o.id)&&String(r.user_id)===String(user.id)));if(!pending.length)return;const result=await supabase.from('occurrence_reads').upsert(pending.map(o=>({occurrence_id:o.id,user_id:user.id})),{onConflict:'occurrence_id,user_id',ignoreDuplicates:true});if(result.error){setMessage('Não foi possível registrar a visualização: '+result.error.message);return;}setReads(prev=>[...prev,...pending.map(o=>({occurrence_id:o.id,user_id:user.id}))]);};
