const visibleItems=user?.role==='client'&&selectedMarket?items.filter(o=>String(o.market_id)===selectedMarket):items;const activeMarket=markets.find(m=>String(m.id)===selectedMarket)||markets[0]||null;const negativeItems=visibleItems.filter(o=>o.type!=='Sem ocorrência'&&o.type!=='Verificação preventiva');const currentMonth=new Date().toLocaleDateString('en-CA').slice(0,7);const monthlyNegative=negativeItems.filter(o=>o.date?.startsWith(currentMonth));const unreadItems=(user?.role==='client'&&selectedMarket&&markets.some(m=>String(m.id)===String(selectedMarket))?negativeItems:[]).filter(o=>!reads.some(r=>String(r.occurrence_id)===String(o.id)&&String(r.user_id)===String(user?.id)));const unreadNegative=monthlyNegative.filter(o=>!reads.some(r=>r.occurrence_id===o.id&&r.user_id===user?.id));const historyMonths=[...new Set([currentMonth,...visibleItems.map(o=>o.date?.slice(0,7)).filter(Boolean)])].sort().reverse();const monthLabel=month=>new Date(Number(month.slice(0,4)),Number(month.slice(5,7))-1,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'});const openDashboardView=view=>{setShowAccount(false);setDashboardView(view);setSelectedDate('');setShowCalendar(false);window.scrollTo(0,0)};const chartItems=negativeItems.filter(o=>user?.role==='client'||reportMarket==='todos'||String(o.market_id)===reportMarket);
