const uploadMarketPhoto=async(e)=>{const file=e.target.files?.[0];if(!file||!activeMarket)return;e.target.value='';if(!['image/jpeg','image/png','image/webp'].includes(file.type)){setMessage('Escolha uma imagem JPG, PNG ou WebP.');return}if(file.size>4*1024*1024){setMessage('A imagem deve ter no máximo 4 MB.');return}setAvatarBusy(true);try{const path=String(activeMarket.id)+'/'+crypto.randomUUID()+'.'+(file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg');check(await supabase.storage.from('market-avatars').upload(path,file,{contentType:file.type,upsert:false}));try{check(await supabase.from('markets').update({avatar_path:path}).eq('id',activeMarket.id));}catch(err){await supabase.storage.from('market-avatars').remove([path]);throw err;}await refresh(user);setMessage('Foto do mercado atualizada com sucesso.')}catch(err){setMessage('Não foi possível salvar a foto: '+err.message+' Confira a configuração de fotos no Supabase.')}finally{setAvatarBusy(false)}};
