const adminPhoto=async(e,kind,targetId)=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>4*1024*1024){setManageNotice({type:'error',text:'Escolha uma foto JPG, PNG ou WebP de até 4 MB.'});return}if(busy)return;setBusy('Enviando foto');setManageNotice(null);try{const ids=kind==='client'?{userId:targetId}:{marketId:Number(targetId)};const ticket=await api('/manage-clients',{method:'POST',body:JSON.stringify({action:'photo-ticket',kind,mime:file.type,...ids})});const bucket=kind==='client'?'profile-avatars':'market-avatars';check(await supabase.storage.from(bucket).uploadToSignedUrl(ticket.path,ticket.token,file,{contentType:file.type}));await api('/manage-clients',{method:'POST',body:JSON.stringify({action:'photo-save',kind,path:ticket.path,...ids})});await refresh(user);setManageNotice({type:'success',text:'Foto atualizada com sucesso.'})}catch(err){setManageNotice({type:'error',text:'Não foi possível atualizar a foto: '+err.message})}finally{setBusy('')}};
